    "/tickers/{ticker}/open-close": {
      "get": {
        "summary": "Get Open/Close Stock Data",
        "operationId": "get-tickers-ticker-open-close",
        "parameters": [
          {
            "schema": {
              "type": "string"
            },
            "name": "ticker",
            "in": "path",
            "required": true,
