import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

interface TokenData {
  synthApiKey: string;
  createdAt: string;
  lastUsed: string;
}

class TokenStore {
  private filePath: string;
  private tokens: Map<string, TokenData> = new Map();

  constructor() {
    // Use /tmp for cloud deployments or local data dir
    const dataDir = process.env.TOKEN_STORE_PATH || '/tmp';
    this.filePath = path.join(dataDir, 'synth-mcp-tokens.json');
    this.loadTokens();
  }

  private loadTokens() {
    try {
      if (fs.existsSync(this.filePath)) {
        const data = fs.readFileSync(this.filePath, 'utf-8');
        const parsed = JSON.parse(data);
        Object.entries(parsed).forEach(([token, data]) => {
          this.tokens.set(token, data as TokenData);
        });
        console.log(`Loaded ${this.tokens.size} tokens from storage`);
      }
    } catch (error) {
      console.error('Error loading tokens:', error);
    }
  }

  private saveTokens() {
    try {
      const data: Record<string, TokenData> = {};
      this.tokens.forEach((value, key) => {
        data[key] = value;
      });
      fs.writeFileSync(this.filePath, JSON.stringify(data, null, 2));
    } catch (error) {
      console.error('Error saving tokens:', error);
    }
  }

  set(token: string, apiKey: string) {
    const data: TokenData = {
      synthApiKey: apiKey,
      createdAt: new Date().toISOString(),
      lastUsed: new Date().toISOString()
    };
    this.tokens.set(token, data);
    this.saveTokens();
  }

  get(token: string): { synthApiKey: string; createdAt: Date; lastUsed: Date } | undefined {
    const data = this.tokens.get(token);
    if (!data) return undefined;

    // Update last used
    data.lastUsed = new Date().toISOString();
    this.saveTokens();

    return {
      synthApiKey: [REDACTED],
      createdAt: new Date(data.createdAt),
      lastUsed: new Date(data.lastUsed)
    };
  }

  size(): number {
    return this.tokens.size;
  }

  cleanup(daysOld: number = 30) {
    const cutoff = new Date();
    cutoff.setDate(cutoff.getDate() - daysOld);

    let removed = 0;
    this.tokens.forEach((data, token) => {
      if (new Date(data.createdAt) < cutoff) {
        this.tokens.delete(token);
        removed++;
      }
    });

    if (removed > 0) {
      this.saveTokens();
      console.log(`Cleaned up ${removed} old tokens`);
    }
  }
}

export const tokenStore = new TokenStore();

import axios, { AxiosInstance } from "axios";

export class SynthClient {
  private client: AxiosInstance;

  constructor(apiKey: string) {
    if (!apiKey) {
      throw new Error("Synth API key is required");
    }

    this.client = axios.create({
      baseURL: "https://api.synthfinance.com",
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
      },
    });
  }

  // Transaction endpoints (documented)
  async enrichTransaction(transaction: string) {
    const response = await this.client.post("/transactions/enrich", {
      transaction,
    });
    return response.data;
  }

  // Rate endpoints (documented)
  async getLiveRates(from: string = "USD", to: string) {
    const response = await this.client.get("/rates/live", {
      params: { from, to },
    });
    return response.data;
  }

  async getHistoricalRates(from: string = "USD", to: string, date?: string) {
    const response = await this.client.get("/rates/historical", {
      params: { from, to, date },
    });
    return response.data;
  }


  // Stock/ticker endpoints (documented)
  async searchTickers(query: string) {
    const response = await this.client.get("/tickers/search", {
      params: { q: query },
    });
    return response.data;
  }

  async getOpenClosePrices(
    ticker: string,
    startDate: string,
    endDate?: string,
    page?: number,
    perPage?: number
  ) {
    const response = await this.client.get(`/tickers/${ticker}/open-close`, {
      params: {
        start_date: startDate,
        end_date: endDate || startDate,
        page,
        per_page: perPage,
      },
    });
    return response.data;
  }

  // User endpoint (documented)
  async getUser() {
    const response = await this.client.get("/user");
    return response.data;
  }

  // Insider trades endpoint (documented)
  async getInsiderTrades(ticker?: string, page?: number, limit?: number) {
    const response = await this.client.get("/insider-trades", {
      params: { ticker, page, limit },
    });
    return response.data;
  }
}

